	"ACCOUNTING_TEAM" VARCHAR(65535),
	"IS_ACTIVE" VARCHAR(65535),
	"TEAM_NAME" VARCHAR(65535),
	"PERFORMANCE_REPORTING_INSTANCE_FIRM_ID" VARCHAR(65535),
	"PERFORMANCE_REPORTING_INSTANCE_NAME" VARCHAR(65535),
	"CREATEDDATE" VARCHAR(65535),
	"CREATEDBYID" VARCHAR(65535),
	"LASTMODIFIEDDATE" VARCHAR(65535),
	"LASTMODIFIEDBYID" VARCHAR(65535),
	"CREATED_DTM" VARCHAR(65535),
	"BATCH_NUMBER" VARCHAR(65535),
	"FILE_DATE" VARCHAR(65535),
	"LAST_MODIFIED_TIMEZONE" VARCHAR(65535),
	"CHECKSUM" VARCHAR(65535),
	"PREVIOUS_CHECKSUM" VARCHAR(65535),
	"DAYS_SINCE_LAST_UPDATE" VARCHAR(65535),
	"LAST_UPDATE_RANK" VARCHAR(65535)
)
AS
SELECT
    CAST(NULL AS VARCHAR(65535)) AS "AUTO_INCR_PK",
    CAST(NULL AS VARCHAR(65535)) AS "ID",
    CAST(NULL AS VARCHAR(65535)) AS "OWNERID",
    CAST(NULL AS VARCHAR(65535)) AS "ISDELETED",
    CAST(NULL AS VARCHAR(65535)) AS "DEFAULT_PERFORMANCE_INSTANCE",
    CAST(NULL AS VARCHAR(65535)) AS "ACCOUNTING_TEAM_GL_CODE",
    CAST(NULL AS VARCHAR(65535)) AS "ACCOUNTING_TEAM_NAME",
    CAST(NULL AS VARCHAR(65535)) AS "LASTREFERENCEDDATE",
    CAST(NULL AS VARCHAR(65535)) AS "LASTVIEWEDDATE",
    CAST(NULL AS VARCHAR(65535)) AS "PERFORMANCE_REPORTING_SYSTEM",
    CAST(NULL AS VARCHAR(65535)) AS "DEFAULT_BILLING_PROGRAM",
    CAST(NULL AS VARCHAR(65535)) AS "IS_ELIGIBLE",
    CAST(NULL AS VARCHAR(65535)) AS "NAME",
    CAST(NULL AS VARCHAR(65535)) AS "SYSTEMMODSTAMP",
    CAST(NULL AS VARCHAR(65535)) AS "ACCOUNTING_TEAM",
    CAST(NULL AS VARCHAR(65535)) AS "IS_ACTIVE",
    CAST(NULL AS VARCHAR(65535)) AS "TEAM_NAME",
    CAST(NULL AS VARCHAR(65535)) AS "PERFORMANCE_REPORTING_INSTANCE_FIRM_ID",
    CAST(NULL AS VARCHAR(65535)) AS "PERFORMANCE_REPORTING_INSTANCE_NAME",
    CAST(NULL AS VARCHAR(65535)) AS "CREATEDDATE",
    CAST(NULL AS VARCHAR(65535)) AS "CREATEDBYID",
    CAST(NULL AS VARCHAR(65535)) AS "LASTMODIFIEDDATE",
    CAST(NULL AS VARCHAR(65535)) AS "LASTMODIFIEDBYID",
    CAST(NULL AS VARCHAR(65535)) AS "CREATED_DTM",
    CAST(NULL AS VARCHAR(65535)) AS "BATCH_NUMBER",
    CAST(NULL AS VARCHAR(65535)) AS "FILE_DATE",
    CAST(NULL AS VARCHAR(65535)) AS "LAST_MODIFIED_TIMEZONE",
    CAST(NULL AS VARCHAR(65535)) AS "CHECKSUM",
    CAST(NULL AS VARCHAR(65535)) AS "PREVIOUS_CHECKSUM",
    CAST(NULL AS VARCHAR(65535)) AS "DAYS_SINCE_LAST_UPDATE",
    CAST(NULL AS VARCHAR(65535)) AS "LAST_UPDATE_RANK"
FROM (VALUES (0)) AS "_DUMMY" ("_X")
WHERE 1 = 0;

